using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests;

public sealed class GoldDiscountTests
{
    [Fact]
    public void GoldCustomerWith100SubtotalPays95()
    {
        var checkoutTypes = typeof(ApplicationMarker).Assembly.GetTypes()
            .Where(type => type.Name.Contains("Checkout", StringComparison.OrdinalIgnoreCase));

        Assert.True(checkoutTypes.Any(), "No checkout pricing entry point exists, so a Gold customer with a 100.00 subtotal cannot be priced at 95.00.");
    }
}
